    # 提取时长标签，转换为以秒为单位
    def parse_epoch_length(self, epoch_length):
        match = re.match(r"(\d+(?:\.\d+)?)\s*(\w+)", epoch_length)
        if match:
            number = float(match.group(1))
            unit = match.group(2)
            unit_conversion = {'s': 1, 'min': 60, 'hour': 3600, 'h': 3600}
            return number * unit_conversion.get(unit, 1)
        else:
            raise ValueError("Invalid epoch length format")

    def reject_remain_button_click(self, index):
        # 判断是哪一个按钮触发了点击事件
        if index == 1:
            self.user_edit_stage("Remain")
        elif index == 2:
            self.user_edit_stage("Reject")

    def user_edit_stage(self, action_str):
        """处理用户编辑的坏段拒绝阶段"""
        # 如果是由点击事件触发的更改，则忽略
        if self._ignore_combobox_change:
            return
        try:
            if self.current_selected_epochs is not None:
                new_stage = action_str
                stage_code = 1 if new_stage == "Reject" else 0
                for selected_epoch in self.current_selected_epochs:
                    # 取的是索引
                    self.reject_score_wh.record(selected_epoch, self.df_score.at[selected_epoch, 'Stage_Code'])
                    self.df_score.at[selected_epoch, 'Stage_Code'] = stage_code
                    self.df_score.at[selected_epoch, 'Stage'] = new_stage

        except Exception as e:
            QLLogging.log.exception(f"user_edit_stage error: {e}")

        # 重新绘图
        self.update_plot()

        self.edit_post_process()

    def extract_intervals(self, df, column_name='Stage_Code', value=1.0):
        try:
            # 确保 Epoch No. 是数值类型
            if not pd.api.types.is_numeric_dtype(df['Epoch No.']):
                df['Epoch No.'] = pd.to_numeric(df['Epoch No.'], errors='coerce')

            # 找出满足条件的行
            mask = (df[column_name] == value)

            # 处理没有匹配值的情况
            if not mask.any():
                return []

            # 标记连续区间的开始与结束
            group = (~mask).cumsum()

            # 提取每个连续区间的起始和结束 Epoch No.
            intervals = df.loc[mask, 'Epoch No.'].groupby(group[mask]).agg(['min', 'max']).values.tolist()

        except Exception as e:
            QLLogging.log.exception(f"extract_intervals error: {e}")

        return [[start, end] for start, end in intervals]

    def delete_intervals_in_df_score(self, df_score):
        # 删除索引，最后一个区间的内容没有删除
        # 确保 Epoch No. 列是数值类型
        if not pd.api.types.is_numeric_dtype(df_score['Epoch No.']):
            try:
                df_score['Epoch No.'] = pd.to_numeric(df_score['Epoch No.'], errors='coerce')
            except Exception as e:
                QLLogging.log.error(f"Failed to convert 'Epoch No.' to numeric: {e}")
                return df_score  # 无法转换时返回原始数据

        # 检查并处理 Epoch No. 列中的 NaN
        if df_score['Epoch No.'].isna().any():
            QLLogging.log.warning("Found NaN in 'Epoch No.' column, filling with -1")
            df_score['Epoch No.'].fillna(-1, inplace=True)  # 填充为无效值，确保不被选中

        # 提取要删除的区间
        intervals_to_remove = self.extract_intervals(df_score)

        # 验证区间有效性
        valid_intervals = []
        for start, end in intervals_to_remove:
            if pd.notna(start) and pd.notna(end) and start <= end:
                valid_intervals.append([start, end])
            else:
                QLLogging.log.warning(f"Invalid interval: [{start}, {end}], skipping")

        # 创建筛选掩码
        mask = pd.Series(False, index=df_score.index)

        # 应用有效区间的筛选条件
        for start, end in valid_intervals:
            interval_mask = (df_score['Epoch No.'] >= start) & (df_score['Epoch No.'] <= end)
            mask |= interval_mask

        # 过滤数据
        filtered_df = df_score[~mask].copy()  # 使用 .copy() 避免 SettingWithCopyWarning

        # 重置索引
        filtered_df.reset_index(drop=True, inplace=True)

        return filtered_df

    def edit_post_process(self):
        if self.reject_score_wh.is_empty():
            self.reject_between_widget.reject_between_top_widget.pushButton_undo.setEnabled(False)
        else:
            self.reject_between_widget.reject_between_top_widget.pushButton_undo.setEnabled(True)

        self.reject_between_widget.reject_between_top_widget.pushButton_redo.setEnabled(False)
        self.reject_redo_score_wh.clear()

    def undo_edit(self):
        # 重写 undo 事件
        self.prepare_score_when_undo()
        self.refresh_reject_score()
        self.undo_post_process()

    def redo_edit(self):
        self.prepare_score_when_redo()
        self.refresh_reject_score()
        self.redo_post_process()

    def reset_edit(self):
        while not self.reject_score_wh.is_empty():
            self.prepare_score_when_reset()
            self.refresh_reject_score()

        self.clear_all_rectangles()

        self.reject_redo_score_wh.clear()
        self.reject_score_wh.clear()
        self.reject_between_widget.reject_between_top_widget.pushButton_undo.setEnabled(False)
        self.reject_between_widget.reject_between_top_widget.pushButton_redo.setEnabled(False)

    def refresh_reject_score(self):
        # 重新计算坏段拒绝阶段统计
        stage_counts = self.df_score["Stage_Code"].value_counts()
        self.df_score.loc[0, "Remain_Count"] = stage_counts.get(1, 0)
        self.df_score.loc[0, "Reject_Count"] = stage_counts.get(2, 0)

        self.update_plot()

    def prepare_score_when_undo(self):
        restore_data = self.reject_score_wh.get_restore_data()
        if len(restore_data) == 0:
            return
        for key, value in restore_data.items():
            self.reject_redo_score_wh.record(key, self.df_score.at[key, 'Stage_Code'])
            self.df_score.at[key, 'Stage_Code'] = value
            self.df_score.at[key, 'Stage'] = self.map_stages[value]

    def undo_post_process(self):
        self.reject_between_widget.reject_between_top_widget.pushButton_redo.setEnabled(True)
        if self.reject_score_wh.is_empty():
            self.reject_between_widget.reject_between_top_widget.pushButton_undo.setEnabled(False)

    def prepare_score_when_redo(self):
        restore_data = self.reject_redo_score_wh.get_restore_data()
        if len(restore_data) == 0:
            return
        for key, value in restore_data.items():
            self.reject_score_wh.record(key, self.df_score.at[key, 'Stage_Code'])
            self.df_score.at[key, 'Stage_Code'] = value
            self.df_score.at[key, 'Stage'] = self.map_stages[value]

    def redo_post_process(self):
        self.reject_between_widget.reject_between_top_widget.pushButton_undo.setEnabled(True)
        if self.reject_redo_score_wh.is_empty():
            self.reject_between_widget.reject_between_top_widget.pushButton_redo.setEnabled(False)

    def prepare_score_when_reset(self):
        # 将现在的reject_score清空
        restore_data = self.reject_score_wh.get_restore_data()
        if len(restore_data) == 0:
            return
        for key, value in restore_data.items():
            self.df_score.at[key, 'Stage_Code'] = value
            self.df_score.at[key, 'Stage'] = self.map_stages[value]

    def parse_epoch_amplitude(self, epoch_amplitude):
        numeric_values = re.findall(r'\d+', epoch_amplitude)
        if numeric_values:
            return int(numeric_values[0])
        else:
            QLLogging.log.exception(f"警告：在 {epoch_amplitude} 中未找到数字值")
            return 0

    def get_df_score(self):
        try:
            # 这个是分割成多少个单元格
            import datetime
            start_time = self.raw.info['meas_date']
            end_time = start_time + datetime.timedelta(
                seconds=self.raw.n_times / self.raw.info['sfreq'])

            # 计算时间差值(总秒数）
            time_diff = end_time - start_time

            current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())

            total_utils = (time_diff.total_seconds() + current_epoch_length - 1) // current_epoch_length

            total_utils_list = [0 for _ in range(int(total_utils))]

            df_score = pd.DataFrame({
                "Epoch No.": list(range(len(total_utils_list))),
                "Stage_Code": total_utils_list
            })
            # 添加阶段名称
            stage_code = {0: "Remain", 1: "Reject"}
            df_score["Stage"] = df_score["Stage_Code"].map(stage_code)

            # 保存结果到内存以供后续使用
            self.df_score = df_score

        except Exception as e:
            QLLogging.log.exception(f"get_df_score error: {e}")

    def update_plot(self):
        """绘制分析结果，共用一个滚动区域"""
        QLLogging.log.debug("Plot the results of the analysis")
        if self.df_score is None or self.raw is None:
            QLLogging.log.info("No score data or raw data available")
            return

        self.reject_between_widget.widget_time_slider.time_slider.setTotalPages(int(self.get_new_total_page()))

        # 这里有 raw.info
        self.set_label_time_slider_diff()

