    def _add_rejection_regions(self, ax, scores, epoch_length):
        """为单个轴添加拒绝区域标记"""
        # 合并连续的高亮区域
        merged_regions = []
        current_start = None
        current_end = None

        for axi, is_reject in enumerate(scores):
            if is_reject:
                start = axi * epoch_length
                end = (axi + 1) * epoch_length

                if current_start is None:
                    current_start = start
                    current_end = end
                else:
                    if start <= current_end:
                        current_end = end
                    else:
                        merged_regions.append((current_start, current_end))
                        current_start = start
                        current_end = end

        if current_start is not None:
            merged_regions.append((current_start, current_end))

        # 使用 PolyCollection 批量绘制
        if merged_regions:
            ymin, ymax = ax.get_ylim()
            verts = []

            for start, end in merged_regions:
                verts.append([
                    (start, ymin),
                    (start, ymax),
                    (end, ymax),
                    (end, ymin),
                    (start, ymin),  # 闭合多边形
                ])

            poly = PolyCollection(verts, facecolors='red', alpha=0.3)
            ax.add_collection(poly)
