    # 翻页方法
    def previous_page(self):
        self.next_prev_page = True

        if self.current_page > 1:
            self.current_page -= 1
        else:
            self.current_page = int(self.get_new_total_page())

        # 计算目标页面的时间偏移（秒）
        n_epochs_display = self.get_n_epochs_display()
        current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())
        target_time_sec = (self.current_page - 1) * (n_epochs_display * current_epoch_length)

        # 设置滑块位置
        self.reject_between_widget.widget_time_slider.time_slider.setValue(int(target_time_sec))

        self.update_plot()

    def next_page(self):
        self.next_prev_page = True

        if self.current_page < int(self.get_new_total_page()):
            self.current_page += 1
        else:
            self.current_page = 1

        # 计算目标页面的时间偏移（秒）
        n_epochs_display = self.get_n_epochs_display()
        current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())
        target_time_sec = (self.current_page - 1) * (n_epochs_display * current_epoch_length)

        # 设置滑块位置
        self.reject_between_widget.widget_time_slider.time_slider.setValue(int(target_time_sec))

        self.update_plot()

    def update_page_number(self):
        # 这里需要将总页数 = 总时间 / (每一页的数量 * 单位)
        new_total_page = int(self.get_new_total_page())
        # 如果当前页大于最后一页，则回到第一页
        if self.current_page > new_total_page:
            self.current_page = 1
            self.reject_between_widget.widget_time_slider.time_slider.setValue(0)

        self.top_widget.nav_buttons_widget.label_of_page.setText(f" of {new_total_page}")
        self.top_widget.nav_buttons_widget.button_goto_epoch.setText(str(self.current_page))

    def get_total_time_number(self):
        import datetime
        start_time = self.raw.info['meas_date']
        end_time = start_time + datetime.timedelta(
            seconds=self.raw.n_times / self.raw.info['sfreq'])

        # 计算时间差值(总秒数）
        time_diff = end_time - start_time

        return time_diff

    def get_new_total_page(self):
        # 计算时间差值(总秒数）
        time_diff = self.get_total_time_number()

        # 获取number_epoch
        if self.top_widget.combobox_select_n_epochs.currentText() == "All":
            self.reject_between_widget.widget_time_slider.hide()
            n_epochs_display = self.total_pages
        else:
            self.reject_between_widget.widget_time_slider.show()
            n_epochs_display = int(self.top_widget.combobox_select_n_epochs.currentText())

        current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())

        new_total_page = time_diff.total_seconds() / (n_epochs_display * current_epoch_length)

        return max(1,new_total_page)

