    def import_raw(self, raw):
        """导入数据并初始化显示"""
        self.raw = raw
        self.raw_modified = self.raw.copy()
        self.history = [self.raw_modified.copy()]

        # 检测数据长度并禁用不合适的时间选项
        self.detect_length(raw)

        # 计算总页数
        total_duration = self.raw.n_times / self.raw.info['sfreq']

        self.epoch_length = float(self.top_widget.combobox_epoch_length.currentText())
        self.total_pages = int(np.ceil(total_duration / self.epoch_length))

        self.current_page = 1

        self.get_df_score()

        # 设置 time_slider 的最值
        n_epochs_display = self.get_n_epochs_display()
        current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())

        # 设置滑块的最大值
        max_slider_value = max(0, int(self.get_total_time_number().total_seconds()) -
                               int(n_epochs_display * current_epoch_length))
        self.reject_between_widget.widget_time_slider.time_slider.setMaximum(max_slider_value)

    def detect_length(self, raw):
        time = raw.times
        total_duration = time[-1]  # 总时长(秒)

        # 解析所有可选时间跨度并转换为秒
        def get_seconds(time_str):
            value = int(''.join(filter(str.isdigit, time_str)))
            if 'min' in time_str:
                return value * 60
            elif 'hour' in time_str or 'h' in time_str:
                return value * 3600
            return value  # 默认为秒

        # 计算每个选项对应的秒数
        time_options = [(i, get_seconds(option)) for i, option in enumerate(self.combobox_epoch_length_list)]

        # 找到第一个超过数据总时长的选项的索引
        start_index = len(self.combobox_epoch_length_list)  # 默认值设为列表长度
        for index, seconds in time_options:
            if seconds > total_duration:
                start_index = index
                break

        # 禁用不适合的选项
        for index in range(start_index, len(self.combobox_epoch_length_list)):
            index_1 = self.top_widget.combobox_epoch_length.model().index(index, 0)
            self.top_widget.combobox_epoch_length.model().setData(index_1, 0, QtCore.Qt.UserRole - 1)

    def clear_all_rectangles(self):
        self.rectangles = []  # 清空矩形框列表
        self.history = []  # 重置历史记录
        self.update_plot()  # 重新绘制图形以移除所有矩形

    def confirm_rejected_data(self):
        # 获取到要删除的区间
        QLLogging.log.debug("enter confirm_rejected_data")
        self.rectangles = self.extract_intervals(self.df_score)

        if not self.rectangles:
            QLLogging.log.exception("No epochs have been marked for rejection")
            return

        # 判断是否需要删除首段数据
        if self.rectangles[0][0] == 0:
            # 计算需要删除的时间段长度（秒）
            start_time_change = int(self.epoch_length * (self.rectangles[0][1] + 1))

            # 获取原始测量日期
            original_meas_date = self.raw.info['meas_date']

            if original_meas_date is not None:
                # 计算新的测量日期（原始日期加上删除的时间段）
                new_meas_date = original_meas_date + datetime.timedelta(seconds=start_time_change)

                # 使用 MNE 的方法更新测量日期
                if hasattr(self.raw.info, 'set_meas_date'):
                    self.raw.info.set_meas_date(new_meas_date)
                    QLLogging.log.exception(f"测量日期已更新: {original_meas_date} -> {new_meas_date}")

        # 计算并集的时间段
        self.rectangles.sort()
        # 删除已经拒绝的区间
        self.df_score = self.delete_intervals_in_df_score(self.df_score)

        # 计算出要删除的时间区间
        for start_reject, end_reject in self.rectangles:
            start_reject_time = self.seconds_to_hhmmss(start_reject * self.epoch_length)
            end_reject_time = self.seconds_to_hhmmss((end_reject + 1) * self.epoch_length)
            self.history_reject_time.append(start_reject_time + " - " + end_reject_time)
            self.cmp_reject_time.append(start_reject_time + " - " + end_reject_time)

        self.merged_intervals = []  # 清空之前的合并区间
        for start, end in self.rectangles:
            if not self.merged_intervals or self.merged_intervals[-1][1] < start:
                self.merged_intervals.append([start, end])
            else:
                self.merged_intervals[-1][1] = max(self.merged_intervals[-1][1], end)

        # 创建新的 Raw 对象来存储修改后的数据
        new_data = []
        current_pos = 0
        sfreq = self.raw.info['sfreq']

        for start, end in self.merged_intervals:
            start_idx = int(start * sfreq * self.epoch_length)
            end_idx = int((end + 1) * sfreq * self.epoch_length)

            if start_idx > current_pos:
                new_data.append(self.raw._data[:, current_pos:start_idx])
            current_pos = end_idx

        if current_pos < len(self.raw.times):
            new_data.append(self.raw._data[:, current_pos:])

        # 拼接剩余数据
        if new_data:
            # 创建新的数据数组
            concatenated_data = np.concatenate(new_data, axis=1)

            # 创建新的 Raw 对象
            info = self.raw.info.copy()
            new_raw = mne.io.RawArray(concatenated_data, info)
            new_raw.set_annotations(self.raw.annotations)

            # 更新数据
            self.raw = new_raw
            self.raw_modified = new_raw

            # 更新总页数
            total_duration = self.raw.n_times / self.raw.info['sfreq']
            self.total_pages = int(np.ceil(total_duration / self.epoch_length))

            # 如果当前页超出了新的总页数，则回到最后一页
            if self.current_page > self.total_pages:
                self.current_page = max(1, self.total_pages)

            # 发送处理日志和更新后的数据
            rejected_times = self.convert_time_ranges(self.merged_intervals)
            self.rejectlog = f"\nBad epochs rejection: Done\nThe rejected parts are:\n"
            for i, (start, end) in enumerate(rejected_times, 1):
                self.rejectlog += f"{i}. {start} - {end}\n"

            # 发送信号更新主窗口数据
            self.signal_sender.reject_applied.emit(self.raw_modified, self.rejectlog)

        else:
            # 如果没有剩余数据，创建一个空的Raw对象
            empty_data = np.array([]).reshape(len(self.raw.ch_names), 0)
            info = self.raw.info.copy()
            new_raw = mne.io.RawArray(empty_data, info)
            self.raw = new_raw
            self.raw_modified = new_raw
            self.total_pages = 0
            self.current_page = 0
            self.rejectlog = "\nBad epochs rejection: All data has been rejected"
            self.signal_sender.reject_applied.emit(self.raw_modified, self.rejectlog)
            QMessageBox.warning(self.win, 'Warning', 'All data has been rejected!', QMessageBox.Ok)

        # 清空矩形标记
        self.rectangles = []

        # 更新epoch长度
        current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())
        self.epoch_length = current_epoch_length

        # 重新生成数据
        self.get_df_score()
        # 更新页码显示和图形
        #若删除最后末尾的数据，会触发当前页大于总页数的判断，会跳转到第一页
        self.update_page_number()
        self.update_plot()

        n_epochs_display = self.get_n_epochs_display()
        # 设置滑块的最大值
        max_slider_value = max(0, int(self.get_total_time_number().total_seconds()) -
                               int(n_epochs_display * current_epoch_length))
        self.reject_between_widget.widget_time_slider.time_slider.setMaximum(max_slider_value)

        if new_data:  # 只在成功剔除部分数据时显示成功消息
            QMessageBox.information(self.win, 'Rejection Applied', 'All selected epochs have been rejected.',
                                    QMessageBox.Ok)

        # 将 这个 wh 中的数据清空
        self.reset_edit()

    def seconds_to_hhmmss(self, seconds):
        from datetime import timedelta
        # 使用 timedelta 将秒数转换为 HH:MM:SS 格式
        time_delta = timedelta(seconds=seconds)
        hours, remainder = divmod(time_delta.seconds, 3600)
        minutes, seconds = divmod(remainder, 60)
        return f"{hours:02}:{minutes:02}:{seconds:02}"

    def update_rejected_data(self):
        """更新并保存处理后的数据"""
        # 发送处理日志
        if hasattr(self, 'merged_intervals') and self.merged_intervals:
            rejected_times = self.convert_time_ranges(self.merged_intervals)
            self.rejectlog = f"\nBad epochs rejection: Done\nThe rejected parts are:\n"
            for i, (start, end) in enumerate(rejected_times, 1):
                self.rejectlog += f"{i}. {start} - {end}\n"
        else:
            self.rejectlog = "\nBad epochs rejection: No data was rejected"

        # 保存文件
        if self.save_to_edf():  # 如果保存成功
            self.signal_sender.reject_applied.emit(self.raw_modified, self.rejectlog)
            self.win.close()

    def convert_time_ranges(self, time_ranges):
        """
        Convert a list of time ranges in seconds to HH:MM:SS format.
        """
        formatted_times = []
        for start, end in time_ranges:
            # Convert seconds to HH:MM:SS
            start_time = self.seconds_to_hms(start)
            end_time = self.seconds_to_hms(end)
            # Append the formatted time range to the list
            formatted_times.append((start_time, end_time))
        return formatted_times

    def seconds_to_hms(self, seconds):
        """
        Convert seconds to HH:MM:SS format
        """
        hours = int(seconds // 3600)
        minutes = int((seconds % 3600) // 60)
        seconds = int(seconds % 60)
        return f"{hours:02d}:{minutes:02d}:{seconds:02d}"

    def handle_rejected_data(self, raw_modified, reject_log):
        if raw_modified is None:
            # 处理所有数据被剔除的情况
            self.raw = None
            self.processing_log += reject_log
            # 更新界面显示或其他必要的处理
        else:
            # 正常处理
            self.raw = raw_modified
            self.processing_log += reject_log

    def save_to_edf(self):
        """保存处理后的数据为EDF文件"""
        try:
            # 打开文件保存对话框
            options = QtWidgets.QFileDialog.Options()
            file_name, _ = QtWidgets.QFileDialog.getSaveFileName(
                self.win,
                "Save EDF File",
                "",
                "EDF Files (*.edf);;All Files (*)",
                options=options
            )

            if file_name:
                # 如果用户没有添加.edf后缀，自动添加
                if not file_name.lower().endswith('.edf'):
                    file_name += '.edf'

                # 获取数据和参数
                n_channels = len(self.raw_modified.ch_names)
                channel_names = self.raw_modified.ch_names
                sfreq = self.raw_modified.info['sfreq']

                # 创建数据副本
                scaled_data = self.raw_modified._data.copy()

                # 对ACC通道进行缩放
                for i, ch_name in enumerate(channel_names):
                    if 'ACC' in ch_name:
                        scaled_data[i] = scaled_data[i] * 1e-6

                # 创建EDF写入器
                edf_writer = EdfWriter(file_name, n_channels=n_channels)

                # 设置头文件信息
                for i, ch_name in enumerate(channel_names):
                    if 'ACC' in ch_name:  # 对于加速度计通道
                        ch_dict = {
                            'label': ch_name,
                            'dimension': 'mg',  # 加速度单位
                            'sample_rate': int(sfreq),
                            'physical_max': 10000,
                            'physical_min': -10000,
                            'digital_max': 32767,
                            'digital_min': -32768,
                            'transducer': '',
                            'prefilter': ''
                        }
                    else:  # 对于EEG通道
                        ch_dict = {
                            'label': ch_name,
                            'dimension': 'uV',
                            'sample_rate': int(sfreq),
                            'physical_max': 10000,
                            'physical_min': -10000,
                            'digital_max': 32767,
                            'digital_min': -32768,
                            'transducer': '',
                            'prefilter': ''
                        }
                    edf_writer.setSignalHeader(i, ch_dict)

                # 写入缩放后的数据
                edf_writer.writeSamples(scaled_data)

                # 关闭文件
                edf_writer.close()

                QMessageBox.information(
                    self.win,
                    'Success',
                    f'File successfully saved as:\n{file_name}',
                    QMessageBox.Ok
                )
                return True
            return False
        except Exception as e:
            QMessageBox.critical(
                self.win,
                'Error',
                f'Error saving file:\n{str(e)}',
                QMessageBox.Ok
            )
            return False

    def update_display_goto_epoch(self):
        """跳转到特定epoch"""
        try:
            min_value = 1
            max_value = int(self.get_new_total_page())
            prompt = f"Enter the Page You Want to View:[{min_value}, {max_value}]"
            target_page, done = QInputDialog.getInt(
                self.win, 'Input Dialog', prompt,
                min=min_value, max=max_value, value=self.current_page
            )

            if done:
                # 根据目标页码计算滑块位置
                n_epochs_display = self.get_n_epochs_display()
                current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())

                # 计算目标页面的时间偏移（秒）
                target_time_sec = (target_page - 1) * (n_epochs_display * current_epoch_length)

                # 更新当前页面
                self.current_page = target_page

                # 设置滑块位置
                self.reject_between_widget.widget_time_slider.time_slider.setValue(int(target_time_sec))

                self.update_plot()

        except Exception as e:
            QLLogging.log.exception(f"Error in update_display_goto_epoch: {str(e)}")

    def update_display_first(self):
        """显示第一页的结果"""
        if self.current_page != 1:
            self.current_page = 1

            # 第一页对应时间偏移为0
            self.reject_between_widget.widget_time_slider.time_slider.setValue(0)

            self.update_plot()

    def update_display_last(self):
        """显示最后一页的内容"""
        last_page = int(self.get_new_total_page())
        if self.current_page != last_page:
            self.current_page = last_page

            # 最后一页对应总时间
            total_time_sec = int(self.get_total_time_number().total_seconds())
            self.reject_between_widget.widget_time_slider.time_slider.setValue(total_time_sec)

            self.update_plot()

    def update_display_n_epochs(self):
        """更新显示的epoch数量"""
        try:
            n_epochs_display = self.get_n_epochs_display()
            current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())

            # 设置滑块的最大值
            max_slider_value = max(0, int(self.get_total_time_number().total_seconds()) -
                                   int(n_epochs_display * current_epoch_length))
            self.reject_between_widget.widget_time_slider.time_slider.setMaximum(max_slider_value)

            # 获取最近一次状态修改的位置
            last_modified_epoch = self.get_last_modified_epoch()

            if last_modified_epoch is not None:
                # 将epoch位置转换为时间位置（秒）
                target_time_sec = last_modified_epoch * current_epoch_length

                # 确保在有效范围内
                if target_time_sec <= max_slider_value:
                    # 设置滑块位置到最后修改的epoch
                    self.reject_between_widget.widget_time_slider.time_slider.setValue(int(target_time_sec))
                    QLLogging.log.debug(
                        f"Jumped to last modified epoch: {last_modified_epoch}, time: {target_time_sec}s")
                else:
                    # 如果超出范围，设置到最大值
                    self.reject_between_widget.widget_time_slider.time_slider.setValue(max_slider_value)
                    QLLogging.log.debug(f"Last modified epoch out of range, set to max: {max_slider_value}s")
            else:
                # 没有修改记录，确保当前滑块值在有效范围内
                current_slider_value = self.reject_between_widget.widget_time_slider.time_slider.value()
                if current_slider_value > max_slider_value:
                    self.reject_between_widget.widget_time_slider.time_slider.setValue(max_slider_value)

            # 根据滑块值计算当前页码
            slider_time_sec = self.reject_between_widget.widget_time_slider.time_slider.value()
            self.current_page = int(slider_time_sec // (n_epochs_display * current_epoch_length)) + 1

            # 更新页码显示
            self.update_page_number()

            # 更新滑块的总页数
            self.reject_between_widget.widget_time_slider.time_slider.setTotalPages(int(self.get_new_total_page()))

            # 更新显示
            self.update_plot()

        except Exception as e:
            QLLogging.log.exception(f"Error in update_display_n_epochs: {str(e)}")

    def get_last_modified_epoch(self):
        """获取最近一次状态修改的epoch位置"""
        try:
            # 从历史记录中获取最近的修改
            if not self.reject_score_wh.is_empty():
                # 获取最近的修改记录
                last_backup = self.reject_score_wh.get_last_backup()
                if last_backup:
                    # 返回最近修改的epoch中最小的那个（最开始的位置）
                    return min(last_backup.keys())

            return None

        except Exception as e:
            QLLogging.log.exception(f"Error getting last modified epoch: {str(e)}")
            return None

    def set_label_time_slider_diff(self):
        from datetime import datetime, timedelta
        import datetime

        # 获取原始数据的起始时间
        start_time = self.raw.info['meas_date']

        # 使用第二段代码的计算方式
        # 计算总时长（秒），使用最后一个时间点
        total_duration = int(self.raw.times[-1])  # 转换为整数秒

        # 计算结束时间
        end_time = start_time + datetime.timedelta(seconds=total_duration)

        # 计算时间差值
        time_diff = end_time - start_time

        # 使用 total_seconds() 获取包含天数的总秒数
        total_seconds_val = int(time_diff.total_seconds())

        # 将这个差值转换为时分秒的形式
        hours = int(total_seconds_val // 3600)
        minutes = int((total_seconds_val % 3600) // 60)
        seconds = int(total_seconds_val % 60)

        # 格式化输出，不足两位时前面补零
        formatted_time = f"{hours:02}:{minutes:02}:{seconds:02}"

        self.reject_between_widget.widget_time_slider.label_end_time.setText(formatted_time)

    def set_label_time_slider_diff1(self):
        from datetime import datetime, timedelta
        import datetime
        start_time = self.raw.info['meas_date']
        end_time = start_time + datetime.timedelta(
            seconds=self.raw.n_times / self.raw.info['sfreq'])

        # 计算时间差值
        time_diff = end_time - start_time
        # 将这个差值转换为 时分秒 的形式
        hours = int(time_diff.seconds // 3600)
        minutes = int((time_diff.seconds % 3600) // 60)
        seconds = int(time_diff.seconds % 60)

        # 格式化输出，不足两位时前面补零
        formatted_time = f"{hours:02}:{minutes:02}:{seconds:02}"

        self.reject_between_widget.widget_time_slider.label_end_time.setText(formatted_time)  # 如果不满足两位数，需要添加0

    def on_slider_changed(self):
        """处理滑块值变化"""
        try:
            n_epochs_display = self.get_n_epochs_display()
            current_epoch_length = float(self.top_widget.combobox_epoch_length.currentText())

            # 从滑块直接获取时间偏移（秒）
            slider_time_sec = self.reject_between_widget.widget_time_slider.time_slider.value()

            # 确保时间偏移在有效范围内
            max_time_sec = self.get_total_time_number().total_seconds() - n_epochs_display * current_epoch_length
            slider_time_sec = min(slider_time_sec, max(0, max_time_sec))

            # 根据滑块位置计算当前页码
            if self.next_prev_page:
                self.current_page = max(int(slider_time_sec // (n_epochs_display * current_epoch_length)) + 1,
                                        self.current_page)
            else:
                self.current_page = int(slider_time_sec // (n_epochs_display * current_epoch_length)) + 1

            self.next_prev_page = False
            self.update_plot()

        except Exception as e:
            QLLogging.log.exception(f"on_slider_changed error: {str(e)}")

    def get_n_epochs_display(self):
        """获取显示的epoch数量"""
        text = self.top_widget.combobox_select_n_epochs.currentText()
        if text == 'All':
            self.reject_between_widget.widget_time_slider.hide()
            return self.total_pages
        self.reject_between_widget.widget_time_slider.show()
        return int(text)

    def closeEvent(self, event):
        """重写closeEvent以在关闭窗口时完全清理所有资源"""
        try:
            # 清理图形资源
            if hasattr(self, 'figure1'):
                self.figure1.clear()
                plt.close(self.figure1)
                del self.figure1

            if hasattr(self, 'figure2'):
                self.figure2.clear()
                plt.close(self.figure2)
                del self.figure2

            if hasattr(self, 'canvas1'):
                self.canvas1.close()
                del self.canvas1

            if hasattr(self, 'canvas2'):
                self.canvas2.close()
                del self.canvas2

            # 清理数据资源
            data_attributes = [
                'raw',
                'raw_modified',
                'history',
                'rectangles',
                'merged_intervals',
                'df_score',
                'scores',
                'highlight_lines',
                'current_selected_epoch',
                'n_epochs',
                'epoch_start',
            ]

            for attr in data_attributes:
                if hasattr(self, attr):
                    delattr(self, attr)

            # 断开所有信号连接
            self.event_handler1.disconnect_events()
            self.event_handler2.disconnect_events()

            # 重置所有UI元素状态
            self.top_widget.combobox_select_n_epochs.setEnabled(False)

            # 强制多次垃圾回收
            import gc
            gc.collect()
            gc.collect()

            # 打印内存使用情况（用于调试）
            import psutil
            process = psutil.Process()
            QLLogging.log.debug(f"Memory usage after cleanup: {process.memory_info().rss / 1024 / 1024:.2f} MB")

            # 接受关闭事件
            event.accept()

        except Exception as e:
            QLLogging.log.exception(f"Error during window closing: {str(e)}")
            import traceback
            traceback.print_exc()
            event.accept()  # 即使发生错误也关闭窗口
